connectorMethodInfo: {
  "operation": "List",
  "description": "Retrieve records by using Salesforce Object Query Language (SOQL)",
  "method": "POST",
  "path": "/curated_soqlQuery",
  "operationId": "createCurated_soqlQuery",
  "curated": {
    "name": "ExecuteQuery",
    "displayName": "Search using SOQL",
    "description": "Retrieve records using Salesforce Object Query Language (SOQL).",
    "isHidden": false
  },
  "responseDisplayName": "Query results",
  "responseDescription": "The query results",
  "isHidden": true,
  "design": {
    "actions": [
      {
        "actionType": "api",
        "rules": [
          {
            "type": "field",
            "refFieldName": "generateSchema",
            "isCleared": false,
            "isVariable": false
          },
          {
            "type": "field",
            "refFieldName": "query",
            "refFieldValues": [
              "*"
            ],
            "isCleared": false,
            "isVariable": false
          }
        ],
        "name": "GenerateQuerySchema",
        "apiConfiguration": {
          "url": "/generate-soql-schema",
          "method": "POST",
          "body": {
            "query": "{query}"
          }
        },
        "onSuccess": {
          "type": "remap",
          "remapConfiguration": {
            "input": "noop",
            "output": "replace"
          },
          "actions": [
            {
              "actionType": "clearMessages",
              "refFieldName": "query",
              "messages": [
                "schemaAPIErrorMessage",
                "defaultMessage",
                "refreshSchemaMessage"
              ]
            }
          ]
        },
        "onFailure": {
          "type": "remap",
          "remapConfiguration": {
            "input": "noop",
            "output": "noop"
          },
          "actions": [
            {
              "actionType": "showMessages",
              "refFieldName": "query",
              "messages": [
                "schemaAPIErrorMessage"
              ]
            }
          ]
        }
      }
    ],
    "textBlocks": [
      {
        "name": "schemaAPIErrorMessage",
        "text": "Could not generate custom fields schema. Provider message: {errorMessage}. Please validate Query field input and try again",
        "severity": "error"
      }
    ]
  },
  "parameters": [
